<div style="display: flex; flex-wrap: wrap; gap: 15px; align-items: center; justify-content: space-between;">
<div class="gt-operacion"><input type="number" id="gt-k3-p3" class="gt-input-coef" /> · F<sub>3</sub> + <input type="number" id="gt-k2-p3" class="gt-input-coef" /> · F<sub>2</sub> → F<sub>3</sub> <button onclick="gtCheckOp(3, 2, 1, 'gt-k3-p3', 'gt-k2-p3', 'gt-res-op-3', 'gt-row-p3')" class="gt-btn-check">¿Bien?</button> <span id="gt-res-op-3" class="gt-feedback"></span></div>
<div id="gt-row-p3" style="display: none; align-items: center; gap: 10px;">F<sub>3</sub> resultante: ( <input type="number" id="gt-r30-p3" class="gt-input-val" /> <input type="number" id="gt-r31-p3" class="gt-input-val" /> <input type="number" id="gt-r32-p3" class="gt-input-val" /> ) <button onclick="gtCheckRow(3, 2, 1, 'gt-k3-p3', 'gt-k2-p3', ['gt-r30-p3','gt-r31-p3','gt-r32-p3'], 'gt-res-row-3', 4)" class="gt-btn-check">¿Bien?</button> <span id="gt-res-row-3" class="gt-feedback"></span></div>
</div>
</div>
<div id="gt-paso4" class="gt-paso-box" style="display: none; width: 100%; max-width: 750px; background: #fff8e1; border: 2px solid #f57c00; border-radius: 6px; padding: 20px; text-align: center; box-shadow: 0 4px 10px rgba(0,0,0,0.05);"><label style="font-weight: bold; font-size: 1.1em; color: #f57c00;">Observa el número de filas no nulas. ¿Cuál es su rango?</label> <input type="number" id="gt-rank-input" class="gt-input-val" style="margin: 0 10px;" /> <button onclick="gtCheckRank()" class="gt-btn-main">Comprobar</button>
