</style>
<p>
<script>
    // Variables globales para mantener el estado de la matriz
    let gtMatrix = [[0,0,0], [0,0,0], [0,0,0]];
    let gtCurrentStep = 1;

    // Generar matriz aleatoria
    function gtGenerar() {
        let isNat = document.querySelector('input[name="gt-tipo"]:checked').value === 'nat';

        // Bucle para evitar pivotes iniciales nulos o filas problemáticas
        let valid = false;
        while(!valid) {
            for(let i=0; i<3; i++) {
                for(let j=0; j<3; j++) {
                    let val = isNat ? Math.floor(Math.random() * 9) + 1 : Math.floor(Math.random() * 19) - 9;
                    gtMatrix[i][j] = val;
                }
            }
            // Evitamos pivotes iniciales 0
            if(gtMatrix[0][0] !== 0) valid = true;
        }

        gtUpdateDisplay();
        gtResetUI();
    }

    // Actualizar visualización de la matriz
    function gtUpdateDisplay() {
        for(let i=0; i<3; i++) {
            for(let j=0; j<3; j++) {
                let cell = document.getElementById(`gt-m${i}${j}`);
                cell.innerText = gtMatrix[i][j];
                cell.style.color = "#333";
                cell.style.fontWeight = "normal";
            }
        }
    }

    // Resaltar pivote y objetivo
    function gtHighlight(pivotRow, pivotCol, targetRow, targetCol) {
        gtUpdateDisplay(); // Reset colors
        document.getElementById(`gt-m${pivotRow}${pivotCol}`).style.color = "#f57c00";
        document.getElementById(`gt-m${pivotRow}${pivotCol}`).style.fontWeight = "bold";

        document.getElementById(`gt-m${targetRow}${targetCol}`).style.color = "#dc3545";
        document.getElementById(`gt-m${targetRow}${targetCol}`).style.fontWeight = "bold";
    }

    // Reiniciar la interfaz a su estado inicial
    function gtResetUI() {
        document.getElementById('gt-paso1').style.display = 'block';
        document.getElementById('gt-paso2').style.display = 'none';
        document.getElementById('gt-paso3').style.display = 'none';
        document.getElementById('gt-paso4').style.display = 'none';

        let inputs = document.querySelectorAll('#gauss-tutor input[type="number"]');
        inputs.forEach(inp => { inp.value = ''; inp.disabled = false; });

        let btns = document.querySelectorAll('#gauss-tutor .gt-btn-check');
        btns.forEach(btn => btn.disabled = false);

        let feedbacks = document.querySelectorAll('#gauss-tutor .gt-feedback');
        feedbacks.forEach(fb => fb.innerText = '');
        document.getElementById('gt-res-rank').innerText = '';

        document.getElementById('gt-row-p1').style.display = 'none';
        document.getElementById('gt-row-p2').style.display = 'none';
        document.getElementById('gt-row-p3').style.display = 'none';

        gtHighlight(0, 0, 1, 0); // Resalta a11 y a21
    }

    // Comprobar la operación introducida (los coeficientes k)
    function gtCheckOp(stepNum, targetRow, pivotRow, idKTarget, idKPivot, idFeedback, idRowContainer) {
        let kTarget = parseFloat(document.getElementById(idKTarget).value);
        let kPivot = parseFloat(document.getElementById(idKPivot).value);
        let feedback = document.getElementById(idFeedback);

        if(isNaN(kTarget) || isNaN(kPivot)) {
            feedback.innerHTML = '<span class="gt-error">Faltan datos</span>';
            return;
        }

        if(kTarget === 0) {
            feedback.innerHTML = '<span class="gt-error">El coeficiente de la fila a cambiar no puede ser 0</span>';
            return;
        }

        // Columna a anular: 0 para los pasos 1 y 2, columna 1 para el paso 3.
        let colToZero = pivotRow; 

        let valTarget = gtMatrix[targetRow][colToZero];
        let valPivot = gtMatrix[pivotRow][colToZero];

        if ( (kTarget * valTarget) + (kPivot * valPivot) === 0 ) {
            feedback.innerHTML = '<span class="gt-success">¡Correcto!</span>';
            document.getElementById(idRowContainer).style.display = 'flex';
            document.getElementById(idKTarget).disabled = true;
            document.getElementById(idKPivot).disabled = true;
        } else {
            feedback.innerHTML = '<span class="gt-error">No da 0. Revisa.</span>';
        }
    }

    // Comprobar la fila resultante calculada por el alumno
    function gtCheckRow(stepNum, targetRow, pivotRow, idKTarget, idKPivot, idsResult, idFeedback, nextStep) {
        let kTarget = parseFloat(document.getElementById(idKTarget).value);
        let kPivot = parseFloat(document.getElementById(idKPivot).value);
        let feedback = document.getElementById(idFeedback);

        let userRow = [
            parseFloat(document.getElementById(idsResult[0]).value),
            parseFloat(document.getElementById(idsResult[1]).value),
            parseFloat(document.getElementById(idsResult[2]).value)
        ];

        if(userRow.some(isNaN)) {
            feedback.innerHTML = '<span class="gt-error">Faltan datos</span>';
            return;
        }

        // Calcular la fila real
        let realRow = [0,0,0];
        let isCorrect = true;
        for(let j=0; j<3; j++) {
            realRow[j] = (kTarget * gtMatrix[targetRow][j]) + (kPivot * gtMatrix[pivotRow][j]);
            if(userRow[j] !== realRow[j]) isCorrect = false;
        }

        if(isCorrect) {
            feedback.innerHTML = '<span class="gt-success">¡Fila perfecta!</span>';
            // Actualizar la matriz internamente y visualmente
            gtMatrix[targetRow] = realRow;
            gtUpdateDisplay();

            // Bloquear inputs
            idsResult.forEach(id => document.getElementById(id).disabled = true);

            // Mostrar siguiente paso
            if(nextStep === 2) {
                document.getElementById('gt-paso2').style.display = 'block';
                gtHighlight(0, 0, 2, 0); // Resalta a11 y a31
            } else if (nextStep === 3) {
                // Verificar si a22 es 0. Si es 0, no podemos usarlo como pivote en este ejercicio básico.
                if(gtMatrix[1][1] === 0) {
                    // Terminamos prematuramente indicando que ya está escalonada u ocurre algo especial
                    document.getElementById('gt-paso4').style.display = 'block';
                    gtUpdateDisplay(); // Quitar highlights
                } else {
                    document.getElementById('gt-paso3').style.display = 'block';
                    gtHighlight(1, 1, 2, 1); // Resalta a22 y a32
                }
            } else if (nextStep === 4) {
                document.getElementById('gt-paso4').style.display = 'block';
                gtUpdateDisplay(); // Quitar highlights
            }

        } else {
            feedback.innerHTML = '<span class="gt-error">Hay algún error de cálculo.</span>';
        }
    }

    // Comprobar el Rango final
    function gtCheckRank() {
        let userRank = parseInt(document.getElementById('gt-rank-input').value);
        let feedback = document.getElementById('gt-res-rank');

        if(isNaN(userRank)) return;

        let realRank = 0;
        for(let i=0; i<3; i++) {
            if(gtMatrix[i][0] !== 0 || gtMatrix[i][1] !== 0 || gtMatrix[i][2] !== 0) {
                realRank++;
            }
        }

        if(userRank === realRank) {
            feedback.innerHTML = '<span class="gt-success">¡Enhorabuena! Has completado el ejercicio correctamente.</span>';
            feedback.style.color = "#28a745";
        } else {
            feedback.innerHTML = '<span class="gt-error">Incorrecto. Cuenta las filas que no son todo ceros.</span>';
            feedback.style.color = "#dc3545";
        }
    }

    // Inicializar al cargar
    gtGenerar();
</script>
