<style>
    div#matrix-lab .m-input { width: 55px; padding: 8px 5px; text-align: center; border: 1px solid #ced4da; border-radius: 4px; font-size: 1em; font-family: inherit; transition: border-color 0.2s; }
    div#matrix-lab .m-input:focus { outline: none !important; border-color: #0056b3 !important; background-color: #e6f2ff !important; box-shadow: 0 0 5px rgba(0,86,179,0.2) !important; }
    div#matrix-lab .step-box { margin-bottom: 20px; padding: 15px; border-left: 5px solid #0056b3; background: #fdfdff; border-radius: 6px; border: 1px solid #cce0ff; box-shadow: 0 2px 5px rgba(0,0,0,0.05); }

    /* Estilos para las fracciones visuales */
    div#matrix-lab .matrix-view { display: inline-grid; position: relative; padding: 5px 15px; margin: 15px 0; align-items: center; justify-items: center; }
    div#matrix-lab .matrix-view::before, div#matrix-lab .matrix-view::after { content: ""; position: absolute; top: -5px; bottom: -5px; width: 10px; border: 2px solid #333; }
    div#matrix-lab .matrix-view::before { left: 0; border-right: none; }
