    div#matrix-lab .frac-css { display: inline-block; text-align: center; vertical-align: middle; font-size: 0.95em; margin: 0; }
    div#matrix-lab .frac-css span { display: block; padding: 0.1em 0.3em; line-height: 1.2; }
