<p>
<script>
// --- MOTOR DE FRACCIONES ---
function gcd(a, b) {
    a = Math.abs(a); b = Math.abs(b);
    while (b) { let t = b; b = a % b; a = t; }
    return a || 1;
}

function simplify(n, d) {
    if (n === 0) return {n: 0, d: 1};
    if (d < 0) { n = -n; d = -d; }
    let g = gcd(n, d);
    return {n: n / g, d: d / g};
}

function fAdd(a, b) { return simplify(a.n * b.d + b.n * a.d, a.d * b.d); }
function fSub(a, b) { return simplify(a.n * b.d - b.n * a.d, a.d * b.d); }
function fMul(a, b) { return simplify(a.n * b.n, a.d * b.d); }
function fDiv(a, b) { return simplify(a.n * b.d, a.d * b.n); }
function fIsZero(a) { return a.n === 0; }

function toFrac(valStr) {
    let val = parseFloat(valStr);
    if (isNaN(val)) return {n: 0, d: 1};
    let str = val.toString();
    if (!str.includes('.')) return {n: parseInt(val), d: 1};
    let decs = str.split('.')[1].length;
    let d = Math.pow(10, decs);
    return simplify(Math.round(val * d), d);
}

function formatFracCSS(f) {
    if (f.n === 0) return "0";
    if (f.d === 1) return f.n.toString();
    let sign = f.n < 0 ? "-" : "";
    return `${sign}<div class="frac-css"><span>${Math.abs(f.n)}</span><span class="fdn">${f.d}</span></div>`;
}

// --- INTERFAZ ---
function createInputs() {
    const r = document.getElementById('rows').value;
    const c = document.getElementById('cols').value;
    const container = document.getElementById('matrix-container');
    container.style.gridTemplateColumns = `repeat(${c}, 1fr)`;
    container.innerHTML = '';
    for(let i=0; i<r*c; i++) {
        container.innerHTML += `<input type="number" step="any" id="v${i}" class="m-input" value="0">`;
    }
    document.getElementById('output').style.display = 'none';
}

function fillRandom(type) {
    const r = document.getElementById('rows').value;
    const c = document.getElementById('cols').value;
    for(let i=0; i<r*c; i++) {
        let val = type === 'nat' ? Math.floor(Math.random() * 10) : Math.floor(Math.random() * 19) - 9;
        document.getElementById(`v${i}`).value = val;
    }
    document.getElementById('output').style.display = 'none';
}

function clearMatrix() {
    document.querySelectorAll('.m-input').forEach(input => input.value = 0);
    document.getElementById('output').style.display = 'none';
}

function getMatrixFrac() {
    const r = parseInt(document.getElementById('rows').value);
    const c = parseInt(document.getElementById('cols').value);
    let matrix = [];
    for(let i=0; i<r; i++) {
        matrix[i] = [];
        for(let j=0; j<c; j++) {
            matrix[i][j] = toFrac(document.getElementById(`v${i*c + j}`).value);
        }
    }
    return matrix;
}

function printMatrixHTML(m) {
    let r = m.length;
    let c = m[0].length;
    let html = `<div class="matrix-view" style="grid-template-columns: repeat(${c}, minmax(40px, auto)); gap: 8px 15px;">`;

    for (let i = 0; i < r; i++) {
        for (let j = 0; j < c; j++) {
            html += `<div>${formatFracCSS(m[i][j])}</div>`;
        }
    }
    html += '</div>';
    return html;
}

// --- ALGORITMO GAUSS CON FRACCIONES ---
function calculateGauss() {
    let m = getMatrixFrac();
    let r = m.length;
    let c = m[0].length;
    let stepsArea = document.getElementById('steps-area');
    stepsArea.innerHTML = '';
    document.getElementById('output').style.display = 'block';

    // Copia profunda para las fracciones
    let currentStep = JSON.parse(JSON.stringify(m)); 
    let pivotRow = 0;
    let pivotCol = 0;

    // Matriz inicial
    stepsArea.innerHTML += `<div style="margin-bottom: 20px;"><strong>Matriz Inicial:</strong><br>${printMatrixHTML(currentStep)}</div>`;

    while (pivotRow < r && pivotCol < c) {
        // Buscar pivote no nulo
        let selRow = pivotRow;
        while (selRow < r && fIsZero(currentStep[selRow][pivotCol])) selRow++;

        if (selRow === r) {
            pivotCol++;
            continue;
        }

        // Intercambio si es necesario
        if (selRow !== pivotRow) {
            let temp = currentStep[pivotRow];
            currentStep[pivotRow] = currentStep[selRow];
            currentStep[selRow] = temp;
            stepsArea.innerHTML += `<div class="step-box"><strong style="color: #0056b3;">Intercambiamos Fila ${pivotRow+1} y Fila ${selRow+1}:</strong><br>${printMatrixHTML(currentStep)}</div>`;
        }

        // Hacer ceros debajo
        let stepHtml = `<div class="step-box"><strong style="color: #0056b3;">Hacemos ceros en la Columna ${pivotCol+1} (por debajo de la fila ${pivotRow+1}):</strong><br>`;
        let changed = false;

        for (let i = pivotRow + 1; i < r; i++) {
            if (!fIsZero(currentStep[i][pivotCol])) {
                changed = true;
                // factor = elemento a eliminar / pivote
                let factor = fDiv(currentStep[i][pivotCol], currentStep[pivotRow][pivotCol]);

                // F_i = F_i - factor * F_pivot
                for (let j = pivotCol; j < c; j++) {
                    let termToSub = fMul(factor, currentStep[pivotRow][j]);
                    currentStep[i][j] = fSub(currentStep[i][j], termToSub);
                }
                // Aseguramos el cero exacto visual
                currentStep[i][pivotCol] = {n: 0, d: 1};
            }
        }

        if (changed) {
            stepHtml += printMatrixHTML(currentStep) + `</div>`;
            stepsArea.innerHTML += stepHtml;
        }

        pivotRow++;
        pivotCol++;
    }

    // Calcular rango final
    let rank = 0;
    currentStep.forEach(row => {
        if (row.some(v => !fIsZero(v))) rank++;
    });

    document.getElementById('final-rank').innerHTML = `<strong>Rango final de la matriz = ${rank}</strong>`;
}

// Inicializar al cargar
createInputs();
</script>
