<div class="calc-container">
<div class="instrucciones">
<p>Practica</p>
<ol>
<li>Introduce la matriz A de la que quieras calcular su matriz inversa.</li>
<li>Recuerda que ahora debes calcular el determinante de la matriz que has introducido, ya que solamente se puede calcular la matriz inversa si el determinante es distinto de cero. Cuando lo hayas calculado, pulsa sobre el botón <b>Det(A)</b> para comprobar que lo has hecho bien.</li>
<li>Ahora debes calcular la matriz adjunta de la matriz A. Cuando lo hayas hecho, pulsa sobre el botón <b>Adj(A)</b> y comprueba si la has calculado bien.</li>
<li>Con los datos que tienes, puedes calcular la matriz inversa. Una vez que la hayas calculado, pulsa sobre el botón <b>Inv(A)</b> y comprueba si te ha salido correctamente.</li>
</ol>
</div>
<div class="matrices-wrapper">
<div class="matriz-box">
<h4>Matriz <b>A</b></h4>
<form id="formA" onsubmit="return false;">
<div class="matriz-grid"><input name="a11" type="text" /> <input name="a12" type="text" /> <input name="a13" type="text" /> <input name="a21" type="text" /> <input name="a22" type="text" /> <input name="a23" type="text" /> <input name="a31" type="text" /> <input name="a32" type="text" /> <input name="a33" type="text" /></div>
<div><button class="btn-action btn-borrar" type="button" onclick="limpiarTodo()">Borrar Todo</button></div>
</form></div>
<div class="matriz-box">
<h4>Adjunta de <b>A</b></h4>
<form id="formB" onsubmit="return false;">
<div class="matriz-grid"><input name="a11" type="text" readonly="readonly" /> <input name="a12" type="text" readonly="readonly" /> <input name="a13" type="text" readonly="readonly" /> <input name="a21" type="text" readonly="readonly" /> <input name="a22" type="text" readonly="readonly" /> <input name="a23" type="text" readonly="readonly" /> <input name="a31" type="text" readonly="readonly" /> <input name="a32" type="text" readonly="readonly" /> <input name="a33" type="text" readonly="readonly" /></div>
</form></div>
<div class="matriz-box">
<h4>Inversa de <b>A</b></h4>
<form id="formC" onsubmit="return false;">
<div class="matriz-grid"><input name="a11" type="text" readonly="readonly" /> <input name="a12" type="text" readonly="readonly" /> <input name="a13" type="text" readonly="readonly" /> <input name="a21" type="text" readonly="readonly" /> <input name="a22" type="text" readonly="readonly" /> <input name="a23" type="text" readonly="readonly" /> <input name="a31" type="text" readonly="readonly" /> <input name="a32" type="text" readonly="readonly" /> <input name="a33" type="text" readonly="readonly" /></div>
</form></div>
</div>
<div class="controles-wrapper">
<div class="control-group"><form id="formDeta" onsubmit="return false;"><button class="btn-action" type="button" onclick="calcularDet()">Det(A)</button> <input class="resultado-det" name="output" type="text" readonly="readonly" placeholder="=" /></form></div>
<div class="control-group"><button class="btn-action" type="button" onclick="calcularAdj()">Adj(A)</button></div>
<div class="control-group"><button class="btn-action" type="button" onclick="calcularInv()">Inv(A)</button></div>
</div>
</div>
<p>
<script>
/***************************************************************************
* Lógica JavaScript moderna y robusta para eXeLearning (Con Fracciones)
***************************************************************************/

// Función auxiliar para leer valores de forma segura
function getVal(formId, inputName) {
    let input = document.querySelector('#' + formId + ' input[name="' + inputName + '"]');
    if (!input || input.value.trim() === "") return 0;
    let val = parseFloat(input.value);
    return isNaN(val) ? 0 : val;
}

// Función auxiliar para escribir valores
function setVal(formId, inputName, value) {
    let input = document.querySelector('#' + formId + ' input[name="' + inputName + '"]');
    if (input) input.value = value;
}

// Limpiar todas las matrices
function limpiarTodo() {
    document.getElementById('formA').reset();
    document.getElementById('formB').reset();
    document.getElementById('formC').reset();
    document.getElementById('formDeta').reset();
}

// --- NUEVO: Funciones para manejar fracciones matemáticas ---

// Calcular el Máximo Común Divisor (MCD)
function mcd(a, b) {
    a = Math.abs(a);
    b = Math.abs(b);
    while (b) {
        let t = b;
        b = a % b;
        a = t;
    }
    return a;
}

// Formatear como fracción simplificada
function simplificarFraccion(numerador, denominador) {
    if (numerador === 0) return "0";
    if (denominador === 0) return "NaN"; // No debería pasar si el det != 0

    // Ajustar el signo: que el denominador sea siempre positivo para la vista
    if (denominador < 0) {
        numerador = -numerador;
        denominador = -denominador;
    }

    let divisorComun = mcd(numerador, denominador);
    let num = numerador / divisorComun;
    let den = denominador / divisorComun;

    if (den === 1) {
        return num.toString(); // Es un número entero
    } else {
        return num + "/" + den; // Devuelve formato texto fracción
    }
}

// -------------------------------------------------------------

// Calcular Determinante
function calcularDet() {
    let a11 = getVal('formA', 'a11'), a12 = getVal('formA', 'a12'), a13 = getVal('formA', 'a13');
    let a21 = getVal('formA', 'a21'), a22 = getVal('formA', 'a22'), a23 = getVal('formA', 'a23');
    let a31 = getVal('formA', 'a31'), a32 = getVal('formA', 'a32'), a33 = getVal('formA', 'a33');

    let det = (a11*a22*a33 + a21*a32*a13 + a12*a23*a31) - (a31*a22*a13 + a21*a12*a33 + a32*a23*a11);

    let output = document.querySelector('#formDeta input[name="output"]');
    if(output) output.value = det;

    return det;
}

// Calcular Matriz Adjunta (Matriz de Cofactores)
function calcularAdj() {
    let a11 = getVal('formA', 'a11'), a12 = getVal('formA', 'a12'), a13 = getVal('formA', 'a13');
    let a21 = getVal('formA', 'a21'), a22 = getVal('formA', 'a22'), a23 = getVal('formA', 'a23');
    let a31 = getVal('formA', 'a31'), a32 = getVal('formA', 'a32'), a33 = getVal('formA', 'a33');

    setVal('formB', 'a11', (a22*a33 - a23*a32));
    setVal('formB', 'a12', -1 * (a21*a33 - a23*a31));
    setVal('formB', 'a13', (a21*a32 - a22*a31));

    setVal('formB', 'a21', -1 * (a12*a33 - a13*a32));
    setVal('formB', 'a22', (a11*a33 - a13*a31));
    setVal('formB', 'a23', -1 * (a11*a32 - a12*a31));

    setVal('formB', 'a31', (a12*a23 - a13*a22));
    setVal('formB', 'a32', -1 * (a11*a23 - a21*a13));
    setVal('formB', 'a33', (a11*a22 - a12*a21));
}

// Calcular Matriz Inversa (Traspuesta de la de cofactores / det)
function calcularInv() {
    let det = calcularDet(); 

    if (det === 0) {
        alert("La matriz introducida es singular (determinante 0) y no tiene inversa.");
        return;
    }

    calcularAdj(); 

    let b11 = getVal('formB', 'a11'), b12 = getVal('formB', 'a12'), b13 = getVal('formB', 'a13');
    let b21 = getVal('formB', 'a21'), b22 = getVal('formB', 'a22'), b23 = getVal('formB', 'a23');
    let b31 = getVal('formB', 'a31'), b32 = getVal('formB', 'a32'), b33 = getVal('formB', 'a33');

    // Al colocar b21 en a12 (y viceversa) estamos haciendo la matriz traspuesta
    // Además, se llama a la función de simplificar fracción en lugar de dividir directamente
    setVal('formC', 'a11', simplificarFraccion(b11, det));
    setVal('formC', 'a12', simplificarFraccion(b21, det));
    setVal('formC', 'a13', simplificarFraccion(b31, det));

    setVal('formC', 'a21', simplificarFraccion(b12, det));
    setVal('formC', 'a22', simplificarFraccion(b22, det));
    setVal('formC', 'a23', simplificarFraccion(b32, det));

    setVal('formC', 'a31', simplificarFraccion(b13, det));
    setVal('formC', 'a32', simplificarFraccion(b23, det));
    setVal('formC', 'a33', simplificarFraccion(b33, det));
}
</script>
