<div id="calc-inversa-adjunta" class="solucionador-container">
<div class="solucionador-header"><img src="{{context_path}}/content/resources/20260427133316638D31/yoneco.png" width="60" height="60" alt="" style="margin-bottom: 10px;" />
<h3>Calculadora Paso a Paso: Matriz Inversa (3x3)</h3>
<p>Introduce los valores de la matriz A y pulsa en "Resolver" para ver todo el desarrollo por Adjuntos.</p>
</div>
<div class="input-matriz-wrapper">
<div class="matriz-box-input"><form id="formSolucionador" onsubmit="return false;">
<div class="matriz-css"><input name="s11" type="text" value="1" /> <input name="s12" type="text" value="0" /> <input name="s13" type="text" value="1" /> <input name="s21" type="text" value="2" /> <input name="s22" type="text" value="4" /> <input name="s23" type="text" value="1" /> <input name="s31" type="text" value="-2" /> <input name="s32" type="text" value="0" /> <input name="s33" type="text" value="7" /></div>
</form></div>
</div>
<div class="botones-wrapper"><button class="btn-limpiar" onclick="limpiarSolucionador()">Limpiar</button> <button class="btn-resolver" onclick="ejecutarSolucionador()">Resolver paso a paso</button></div>
<div id="zona-resultados"></div>
</div>
<p>
<script>
// --- NUEVO: Función para limpiar todo ---
function limpiarSolucionador() {
    // Restaura los valores por defecto del formulario (los dejará vacíos o con su value inicial)
    document.getElementById('formSolucionador').reset();

    // Oculta y vacía la zona de resultados
    let zona = document.getElementById("zona-resultados");
    zona.style.display = "none";
    zona.innerHTML = "";
}

// Funciones matemáticas básicas (MCD y Fracciones)
function mcd(a, b) {
    a = Math.abs(a); b = Math.abs(b);
    while (b) { let t = b; b = a % b; a = t; }
    return a;
}

function formatearFraccionCSS(numerador, denominador) {
    if (numerador === 0) return "0";
    if (denominador < 0) { numerador = -numerador; denominador = -denominador; }
    let divisor = mcd(numerador, denominador);
    let num = numerador / divisor;
    let den = denominador / divisor;

    if (den === 1) return num.toString();
    // Construimos la fracción con HTML puro
    return `<div class="frac-css"><span>${num}</span><span class="fdn">${den}</span></div>`;
}

// Generador de matrices HTML puro
function generarMatrizCSS(matriz2D, nombre) {
    let filas = matriz2D.map(fila => fila.map(val => `<div>${val}</div>`).join(' ')).join('\n');
    let prefijo = nombre ? `<b style="margin-right:20px; font-size:1.3em; color:#0056b3;">${nombre} =</b>` : '';
    return `
    <div style="display:flex; align-items:center; justify-content:center; margin: 25px 0; background: #fdfdff; padding: 20px; border-radius: 8px; border: 1px solid #cce0ff;">
        ${prefijo}
        <div class="matriz-css" style="font-family: monospace; font-size: 1.2em;">
            ${filas}
        </div>
    </div>`;
}

// Lógica principal del solucionador
function ejecutarSolucionador() {
    let zona = document.getElementById("zona-resultados");
    zona.style.display = "block";
    zona.innerHTML = "<p>Calculando...</p>";

    // 1. Leer valores (Aceptando comas como decimales por si acaso)
    const getV = (name) => {
        let valStr = document.querySelector('#formSolucionador input[name="'+name+'"]').value.replace(',', '.');
        let val = parseFloat(valStr);
        return isNaN(val) ? 0 : val;
    };

    let a11 = getV('s11'), a12 = getV('s12'), a13 = getV('s13');
    let a21 = getV('s21'), a22 = getV('s22'), a23 = getV('s23');
    let a31 = getV('s31'), a32 = getV('s32'), a33 = getV('s33');

    let htmlSalida = "";

    // 2. Paso 1: Determinante
    htmlSalida += `<h4 class="paso-titulo">Paso 1: Cálculo del determinante |A| (Regla de Sarrus)</h4>`;
    let diagPrinc = (a11*a22*a33) + (a12*a23*a31) + (a21*a32*a13);
    let diagSec = (a13*a22*a31) + (a12*a21*a33) + (a23*a32*a11);
    let det = diagPrinc - diagSec;

    htmlSalida += `
    <div class="calculo-detalle">
        |A| = [(${a11})·(${a22})·(${a33}) + (${a12})·(${a23})·(${a31}) + (${a21})·(${a32})·(${a13})] - <br>
        &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[(${a13})·(${a22})·(${a31}) + (${a12})·(${a21})·(${a33}) + (${a23})·(${a32})·(${a11})]<br><br>
        |A| = [${diagPrinc}] - [${diagSec}] = <b style="font-size: 1.2em;">${det}</b>
    </div>`;

    if (det === 0) {
        htmlSalida += `<div style="margin-top: 25px; padding: 20px; background: #fff5f5; border: 1px solid #ffcdd2; border-radius: 8px; text-align: center;"><p style="color: #dc3545; font-weight: bold; font-size: 1.2em; margin: 0;">¡Atención!</p><p style="color: #444; margin-top: 10px;">El determinante es 0. Como no se puede dividir entre 0 en la fórmula final, esta matriz es singular y <b>NO tiene inversa</b>.</p></div>`;
        zona.innerHTML = htmlSalida;
        return;
    }

    // 3. Paso 2: Matriz Adjunta
    htmlSalida += `<h4 class="paso-titulo">Paso 2: Cálculo de los adjuntos (Cofactores)</h4>`;
    htmlSalida += `<p>Calculamos los menores complementarios aplicando el signo correspondiente (+ ó -):</p>`;

    let c11 = (a22*a33 - a23*a32),   c12 = -1*(a21*a33 - a23*a31),  c13 = (a21*a32 - a22*a31);
    let c21 = -1*(a12*a33 - a13*a32), c22 = (a11*a33 - a13*a31),    c23 = -1*(a11*a32 - a12*a31);
    let c31 = (a12*a23 - a13*a22),   c32 = -1*(a11*a23 - a21*a13),  c33 = (a11*a22 - a12*a21);

    htmlSalida += `
    <div class="calculo-detalle" style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:15px; text-align: center;">
        <div>A<sub>11</sub> = +(${a22}·${a33} - ${a23}·${a32}) = <b>${c11}</b></div>
        <div>A<sub>12</sub> = -(${a21}·${a33} - ${a23}·${a31}) = <b>${c12}</b></div>
        <div>A<sub>13</sub> = +(${a21}·${a32} - ${a22}·${a31}) = <b>${c13}</b></div>

        <div>A<sub>21</sub> = -(${a12}·${a33} - ${a13}·${a32}) = <b>${c21}</b></div>
        <div>A<sub>22</sub> = +(${a11}·${a33} - ${a13}·${a31}) = <b>${c22}</b></div>
        <div>A<sub>23</sub> = -(${a11}·${a32} - ${a12}·${a31}) = <b>${c23}</b></div>

        <div>A<sub>31</sub> = +(${a12}·${a23} - ${a13}·${a22}) = <b>${c31}</b></div>
        <div>A<sub>32</sub> = -(${a11}·${a23} - ${a21}·${a13}) = <b>${c32}</b></div>
        <div>A<sub>33</sub> = +(${a11}·${a22} - ${a12}·${a21}) = <b>${c33}</b></div>
    </div>`;

    htmlSalida += generarMatrizCSS([[c11, c12, c13], [c21, c22, c23], [c31, c32, c33]], "Adj(A)");

    // 4. Paso 3: Traspuesta
    htmlSalida += `<h4 class="paso-titulo">Paso 3: Traspuesta de la matriz adjunta</h4>`;
    htmlSalida += `<p>Cambiamos las filas por columnas para obtener Adj(A)<sup>t</sup>:</p>`;
    htmlSalida += generarMatrizCSS([[c11, c21, c31], [c12, c22, c32], [c13, c23, c33]], "Adj(A)<sup>t</sup>");

    // 5. Paso 4: Matriz Inversa (Fracciones)
    htmlSalida += `<h4 class="paso-titulo">Paso 4: Matriz Inversa (División entre el determinante)</h4>`;
    htmlSalida += `<p>Finalmente, dividimos cada elemento de la matriz traspuesta entre el determinante (|A| = ${det}) y simplificamos las fracciones:</p>`;

    let f11 = formatearFraccionCSS(c11, det), f12 = formatearFraccionCSS(c21, det), f13 = formatearFraccionCSS(c31, det);
    let f21 = formatearFraccionCSS(c12, det), f22 = formatearFraccionCSS(c22, det), f23 = formatearFraccionCSS(c32, det);
    let f31 = formatearFraccionCSS(c13, det), f32 = formatearFraccionCSS(c23, det), f33 = formatearFraccionCSS(c33, det);

    htmlSalida += generarMatrizCSS([[f11, f12, f13], [f21, f22, f23], [f31, f32, f33]], "A<sup>-1</sup>");

    zona.innerHTML = htmlSalida;
}
</script>
