    div#calc-gauss-jordan .matriz-box-input input[type="text"] { width: 55px; padding: 8px 5px; text-align: center; border: 1px solid #aaa; border-radius: 4px; font-size: 1.1em; transition: all 0.2s; font-family: monospace; }
    div#calc-gauss-jordan .matriz-box-input input[type="text"]:focus { outline: none !important; border-color: #0056b3 !important; background-color: #e6f2ff !important; box-shadow: 0 0 5px rgba(0,86,179,0.2) !important; }

    /* Contenedor de botones para centrarlos */
