    div#calc-gauss-jordan button.btn-resolver:hover, div#calc-gauss-jordan button.btn-resolver:focus { background-color: #004494 !important; border-color: #004494 !important; transform: scale(1.02) !important; color: white !important; }

    /* Botón Limpiar (Fantasma Invertido) */
    div#calc-gauss-jordan button.btn-limpiar { background-color: #ffffff !important; background-image: none !important; color: #0056b3 !important; border: 2px solid #0056b3 !important; padding: 12px 25px !important; border-radius: 6px !important; cursor: pointer !important; font-weight: bold !important; font-size: 1.1em !important; transition: all 0.2s ease-in-out !important; box-shadow: none !important; outline: none !important; }
    div#calc-gauss-jordan button.btn-limpiar:hover, div#calc-gauss-jordan button.btn-limpiar:focus { background-color: #e6f2ff !important; border-color: #0056b3 !important; transform: scale(1.02) !important; color: #0056b3 !important; }

    /* Área de resultados y Matriz Ampliada */
    div#calc-gauss-jordan #zona-resultados { margin-top: 30px; display: none; background: #fff; padding: 25px; border-left: 5px solid #0056b3 !important; border-radius: 6px; border: 1px solid #cce0ff; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
    div#calc-gauss-jordan .paso-titulo { color: #0056b3 !important; border-bottom: 2px solid #e6f2ff; padding-bottom: 8px; margin-top: 30px; font-size: 1.2em; }
    div#calc-gauss-jordan .operacion-fila { background-color: #fdfdff; padding: 10px 15px; border-radius: 4px; font-family: monospace; font-size: 1.1em; color: #0056b3; border: 1px dashed #cce0ff; margin: 10px 0; display: inline-block; font-weight: bold; }

    div#calc-gauss-jordan .matriz-ampliada { display: inline-grid; grid-template-columns: repeat(6, minmax(40px, auto)); gap: 12px 20px; position: relative; padding: 10px 25px; text-align: center; align-items: center; margin: 20px 0; background: #fdfdff; border-radius: 4px; font-family: monospace; font-size: 1.2em; }
    div#calc-gauss-jordan .matriz-ampliada::before, div#calc-gauss-jordan .matriz-ampliada::after { content: ""; position: absolute; top: -5px; bottom: -5px; width: 10px; border: 2px solid #333; }
    div#calc-gauss-jordan .matriz-ampliada::before { left: 0; border-right: none; border-radius: 4px 0 0 4px; }
    div#calc-gauss-jordan .matriz-ampliada::after { right: 0; border-left: none; border-radius: 0 4px 4px 0; }
    div#calc-gauss-jordan .matriz-ampliada > div:nth-child(6n+3) { border-right: 2px dashed #ccc; padding-right: 20px; }
    div#calc-gauss-jordan .matriz-ampliada > div:nth-child(6n+4) { padding-left: 10px; }

    div#calc-gauss-jordan .frac-css { display: inline-block; text-align: center; vertical-align: middle; margin: 0 2px; font-size: 0.95em; }
    div#calc-gauss-jordan .frac-css > span { display: block; padding: 0.1em 0.3em; line-height: 1.2; }
    div#calc-gauss-jordan .frac-css span.fdn { border-top: 1px solid #333; }
</style>
<div id="calc-gauss-jordan" class="solucionador-container">
<div class="solucionador-header"><img src="{{context_path}}/content/resources/202604271339346094G1/yoneco.png" width="60" height="60" alt="" style="margin-bottom: 10px;" />
<h3>Calculadora Paso a Paso: Inversa por Gauss-Jordan</h3>
<p style="color: #666; font-size: 0.95em;">Introduce los valores de la matriz A (3x3) y pulsa en "Resolver" para ver las operaciones por filas.</p>
</div>
<div class="input-matriz-wrapper">
<div class="matriz-box-input"><form id="formSolucionador" onsubmit="return false;">
<div class="matriz-css"><input name="s11" type="text" value="3" /> <input name="s12" type="text" value="2" /> <input name="s13" type="text" value="1" /> <input name="s21" type="text" value="5" /> <input name="s22" type="text" value="3" /> <input name="s23" type="text" value="4" /> <input name="s31" type="text" value="1" /> <input name="s32" type="text" value="1" /> <input name="s33" type="text" value="-1" /></div>
</form></div>
</div>
<div class="botones-wrapper"><button class="btn-limpiar" onclick="limpiarSolucionador()">Limpiar</button> <button class="btn-resolver" onclick="ejecutarGauss()">Resolver paso a paso</button></div>
<div id="zona-resultados"></div>
</div>
<p>
<script>
// --- Función para limpiar todo ---
function limpiarSolucionador() {
    document.getElementById('formSolucionador').reset();
    let zona = document.getElementById("zona-resultados");
    zona.style.display = "none";
    zona.innerHTML = "";
}

// --- LIBRERÍA DE FRACCIONES ---
function gcd(a, b) {
    a = Math.abs(a); b = Math.abs(b);
    while (b) { let t = b; b = a % b; a = t; }
    return a || 1;
}

function simplificar(n, d) {
    if (n === 0) return {n: 0, d: 1};
    if (d < 0) { n = -n; d = -d; }
    let g = gcd(n, d);
    return {n: n / g, d: d / g};
}

function fAdd(a, b) { return simplificar(a.n * b.d + b.n * a.d, a.d * b.d); }
function fSub(a, b) { return simplificar(a.n * b.d - b.n * a.d, a.d * b.d); }
function fMul(a, b) { return simplificar(a.n * b.n, a.d * b.d); }
function fDiv(a, b) { return simplificar(a.n * b.d, a.d * b.n); }
function fIsZero(a) { return a.n === 0; }
function fIsOne(a) { return a.n === a.d && a.d !== 0; }
function toFrac(val) {
    let str = val.toString();
    if (!str.includes('.')) return {n: parseInt(val), d: 1};
    let decs = str.split('.')[1].length;
    let d = Math.pow(10, decs);
    return simplificar(Math.round(val * d), d);
}

// --- FORMATEO VISUAL HTML ---
function formatCSS(f) {
    if (f.n === 0) return "0";
    if (f.d === 1) return f.n.toString();
    let sign = f.n < 0 ? "-" : "";
    return `${sign}<div class="frac-css"><span>${Math.abs(f.n)}</span><span class="fdn">${f.d}</span></div>`;
}

function printAmpliada(M) {
    let html = '<div style="text-align:center;"><div class="matriz-ampliada">';
    for (let r = 0; r < 3; r++) {
        for (let c = 0; c < 6; c++) {
            html += `<div>${formatCSS(M[r][c])}</div>`;
        }
    }
    html += '</div></div>';
    return html;
}

function printMatriz3x3(M, colOffset, nombre) {
    let html = `<div style="text-align:center; margin: 25px 0; display: flex; justify-content: center; align-items: center; background: #fdfdff; padding: 20px; border-radius: 8px; border: 1px solid #cce0ff;">`;
    if (nombre) html += `<b style="font-size:1.3em; margin-right:20px; color: #0056b3;">${nombre} =</b>`;
    html += `<div class="matriz-css" style="font-family: monospace; font-size: 1.2em;">`;
    for (let r = 0; r < 3; r++) {
        for (let c = 0; c < 3; c++) {
            html += `<div>${formatCSS(M[r][c + colOffset])}</div>`;
        }
    }
    html += `</div></div>`;
    return html;
}

// --- ALGORITMO DE GAUSS-JORDAN ---
function ejecutarGauss() {
    let zona = document.getElementById("zona-resultados");
    zona.style.display = "block";
    zona.innerHTML = "";

    // Leer inputs
    const getV = (name) => {
        let valStr = document.querySelector('#formSolucionador input[name="'+name+'"]').value.replace(',', '.');
        let val = parseFloat(valStr);
        return isNaN(val) ? 0 : val;
    };

    // Crear matriz [A | I]
    let M = [
        [toFrac(getV('s11')), toFrac(getV('s12')), toFrac(getV('s13')), toFrac(1), toFrac(0), toFrac(0)],
        [toFrac(getV('s21')), toFrac(getV('s22')), toFrac(getV('s23')), toFrac(0), toFrac(1), toFrac(0)],
        [toFrac(getV('s31')), toFrac(getV('s32')), toFrac(getV('s33')), toFrac(0), toFrac(0), toFrac(1)]
    ];

    let htmlOut = `<p style="font-size: 1.05em; color: #444;">Construimos la matriz ampliada <b>[A | I]</b> y aplicamos operaciones elementales por filas para transformar la parte izquierda en la matriz identidad.</p>`;
    htmlOut += printAmpliada(M);

    let paso = 1;

    for (let i = 0; i < 3; i++) {
        // Pivotaje
        if (fIsZero(M[i][i])) {
            let swapped = false;
            for (let k = i + 1; k < 3; k++) {
                if (!fIsZero(M[k][i])) {
                    let temp = M[i]; M[i] = M[k]; M[k] = temp;
                    htmlOut += `<h4 class="paso-titulo">Paso ${paso++}: Intercambiar filas</h4>`;
                    htmlOut += `<div class="operacion-fila">F<sub>${i+1}</sub> &harr; F<sub>${k+1}</sub></div>`;
                    htmlOut += printAmpliada(M);
                    swapped = true;
                    break;
                }
            }
            if (!swapped) {
                htmlOut += `<div style="margin-top: 25px; padding: 20px; background: #fff5f5; border: 1px solid #ffcdd2; border-radius: 8px; text-align: center;"><p style="color: #dc3545; font-weight: bold; font-size: 1.2em; margin: 0;">¡Atención!</p><p style="color: #444; margin-top: 10px;">No se puede encontrar un pivote distinto de cero en la columna ${i+1}. La matriz es singular (determinante 0) y <b>NO tiene inversa</b>.</p></div>`;
                zona.innerHTML = htmlOut;
                return;
            }
        }

        // Hacer 1 el pivote
        if (!fIsOne(M[i][i])) {
            htmlOut += `<h4 class="paso-titulo">Paso ${paso++}: Conseguir un 1 en la posición a<sub>${i+1}${i+1}</sub></h4>`;
            let factorDiv = M[i][i];
            let invFactor = simplificar(factorDiv.d, factorDiv.n); 
            htmlOut += `<div class="operacion-fila">F<sub>${i+1}</sub> &rarr; ${formatCSS(invFactor)} &middot; F<sub>${i+1}</sub></div>`;

            for (let c = 0; c < 6; c++) {
                M[i][c] = fDiv(M[i][c], factorDiv);
            }
            htmlOut += printAmpliada(M);
        }

        // Hacer ceros
        let cerosHechos = false;
        let opTexto = "";

        for (let j = 0; j < 3; j++) {
            if (i !== j && !fIsZero(M[j][i])) {
                if (!cerosHechos) {
                    htmlOut += `<h4 class="paso-titulo">Paso ${paso++}: Hacer ceros en la columna ${i+1}</h4>`;
                    cerosHechos = true;
                }

                let factorZero = M[j][i];
                let opFila = "";

                if (factorZero.n < 0) {
                    let absFact = {n: -factorZero.n, d: factorZero.d};
                    opFila = fIsOne(absFact) ? `F<sub>${j+1}</sub> &rarr; F<sub>${j+1}</sub> + F<sub>${i+1}</sub>` 
                                             : `F<sub>${j+1}</sub> &rarr; F<sub>${j+1}</sub> + ${formatCSS(absFact)} &middot; F<sub>${i+1}</sub>`;
                } else {
                    opFila = fIsOne(factorZero) ? `F<sub>${j+1}</sub> &rarr; F<sub>${j+1}</sub> - F<sub>${i+1}</sub>` 
                                                : `F<sub>${j+1}</sub> &rarr; F<sub>${j+1}</sub> - ${formatCSS(factorZero)} &middot; F<sub>${i+1}</sub>`;
                }

                opTexto += `<div class="operacion-fila" style="margin-right:15px;">${opFila}</div>`;

                for (let c = 0; c < 6; c++) {
                    let multiplicacion = fMul(factorZero, M[i][c]);
                    M[j][c] = fSub(M[j][c], multiplicacion);
                }
            }
        }

        if (cerosHechos) {
            htmlOut += `<div style="text-align: center;">${opTexto}</div>`;
            htmlOut += printAmpliada(M);
        }
    }

    htmlOut += `<h4 class="paso-titulo">¡Finalizado!</h4>`;
    htmlOut += `<p style="font-size: 1.05em; color: #444;">Como hemos obtenido la matriz identidad en la parte izquierda, la parte derecha es nuestra <b>Matriz Inversa</b>:</p>`;
    htmlOut += printMatriz3x3(M, 3, "A<sup>-1</sup>");

    zona.innerHTML = htmlOut;
}
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
